/** Items of the pop-up menus (top menu, context menus, ribbon drop-downs), described as data. */
import type { IconSetName } from '../core/condFormats';
import type { IconName } from './icons';

/** Small pictures shown in menus and galleries instead of an icon. */
export type Preview =
  /** SVG markup generated by the editor (no user content). */
  | { kind: 'svg'; markup: string; width: number; height: number }
  /** A colour square. */
  | { kind: 'color'; css: string }
  /** A row of colour squares of a theme colour scheme. */
  | { kind: 'theme'; colors: string[] }
  /** "Aa" in a font family. */
  | { kind: 'font'; family: string }
  /** A row of chart colours. */
  | { kind: 'palette'; colors: string[] }
  /** The clipboard icon with the icon of a paste option. */
  | { kind: 'paste'; badge?: IconName }
  /** The icons of a conditional formatting icon set, drawn on a canvas. */
  | { kind: 'icon-set'; set: IconSetName };

export interface MenuGalleryItem {
  title: string;
  preview: Preview;
  onClick: () => void;
  testId?: string;
}

export interface MenuItem {
  /** 'gallery': a grid of previews (data bars, colour scales, icon sets...). */
  type?: 'line' | 'header' | 'gallery';
  title?: string;
  icon?: IconName;
  /** Gallery entries and the number of columns. */
  gallery?: MenuGalleryItem[];
  columns?: number;
  /** Shown instead of the icon (swatches). */
  swatch?: Preview;
  shortcut?: string;
  disabled?: boolean;
  checked?: boolean;
  submenu?: MenuItem[];
  onClick?: () => void;
  testId?: string;
  /** Keeps the menu open after the click (toggles). */
  keepOpen?: boolean;
  /** Tooltip. */
  tip?: string;
}

/** Where a menu opens: the top-left corner (client coordinates), or the rectangle to open next to. */
export type MenuAnchor = { x: number; y: number } | DOMRect;
